package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.EnabledUserEmailTemplateVO;

class EnabledUserEmailTemplateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of enabled user email template of tenant config")
  void test_enabled_user_email_template_value_holder_assign_plain_value() {
    Object holder = new Object();
    EnabledUserEmailTemplateValueHolder<Object> value =
        new EnabledUserEmailTemplateValueHolder<>(holder);
    Assertions.assertSame(holder, value.enabledUserEmailTemplate("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getEnabledUserEmailTemplateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getEnabledUserEmailTemplate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.enabledUserEmailTemplateNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getEnabledUserEmailTemplateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getEnabledUserEmailTemplate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of enabled user email template of tenant config")
  void test_enabled_user_email_template_value_holder_assign_value_object() {
    Object holder = new Object();
    EnabledUserEmailTemplateValueHolder<Object> value =
        new EnabledUserEmailTemplateValueHolder<>(holder);
    EnabledUserEmailTemplateVO vo = EnabledUserEmailTemplateVO.from("one");
    Assertions.assertFalse(value.getEnabledUserEmailTemplateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.enabledUserEmailTemplate(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getEnabledUserEmailTemplateValue().orElseThrow());
    Assertions.assertSame(holder, value.enabledUserEmailTemplate(Optional.empty()));
    Assertions.assertFalse(value.getEnabledUserEmailTemplateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.enabledUserEmailTemplate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getEnabledUserEmailTemplateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of enabled user email template of tenant config against the original")
  void test_enabled_user_email_template_value_holder_read() {
    Object holder = new Object();
    EnabledUserEmailTemplateValueHolder<Object> value =
        new EnabledUserEmailTemplateValueHolder<>(holder);
    EnabledUserEmailTemplateVO vo = EnabledUserEmailTemplateVO.from("one");
    EnabledUserEmailTemplateVO other = EnabledUserEmailTemplateVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getEnabledUserEmailTemplateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readEnabledUserEmailTemplate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readEnabledUserEmailTemplate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.enabledUserEmailTemplate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readEnabledUserEmailTemplate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readEnabledUserEmailTemplate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of enabled user email template of tenant config")
  void test_enabled_user_email_template_value_holder_unset() {
    Object holder = new Object();
    EnabledUserEmailTemplateValueHolder<Object> value =
        new EnabledUserEmailTemplateValueHolder<>(holder);
    EnabledUserEmailTemplateVO vo = EnabledUserEmailTemplateVO.from("one");
    value.enabledUserEmailTemplate(vo);
    Assertions.assertSame(holder,
        value.unsetEnabledUserEmailTemplateIfMatches("enabledUserEmailTemplate_other"));
    Assertions.assertTrue(value.getEnabledUserEmailTemplateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetEnabledUserEmailTemplateIfMatches("enabledUserEmailTemplate"));
    Assertions.assertFalse(value.getEnabledUserEmailTemplateValue().isPresent(),
        "The field name must clear the value");
    value.enabledUserEmailTemplate(vo);
    Assertions.assertSame(holder, value.unsetEnabledUserEmailTemplate());
    Assertions.assertFalse(value.getEnabledUserEmailTemplateValue().isPresent(),
        "Unset must clear the value");
  }
}
